/// <returns></returns>
public Set getDocumentTypes()
{
    TFMCustomFunctionFlow flows;
    Set ret = new Set(Types::String);
    while select flows
    {
        ret.add(flows.TFMMenu+ #postPostFix);
        ret.add(flows.TFMMenu+#lookupPostFix);
    }

    return ret;
}

public container registerMenu()
{
    container               ret = conNull();
    TFMCustomFunctionFlow   flows;
    while select flows
    {
        ret += [flows.TFMMenu , flows.TFMMenu, true, resourceStr(TFMQuarantineOrderIcon)];
    }
    return ret;
}

