public Set getReferenceDataMethods()
{
    Set ret = new Set(Types::String);
    ret.add(methodStr(TFMDocCustomFunctionFlow,CustomFunctionFlowReferenceData));

    return ret;
}

/// <summary>
/// Provides reference data for all the pages, that has been setup in the Custom Function Flow setup.
/// </summary>
/// <returns>A TFMDocumentNodes instance containing all the headers, that needs to be created as reference data.</returns>
public TFMDocumentNodes CustomFunctionFlowReferenceData()
{
    TFMCustomFunctionFlow flows;
    TFMDocumentNodes nodes = TFMDocumentNodes::Construct('Configuration');
    TFMDocumentNode confignode;//  = nodes.getRoot();
    TFMDocumentNode KeyNode;//  = nodes.makeChild(confignode,'Key');
    TFMDocumentNode valueNode;// = nodes.makeChild(configNode,'Value');
    boolean         firstTime = true;
    while select flows
    {
        confignode  = firstTime ? nodes.getRoot() : nodes.makeRootSibling('Configuration');
        KeyNode     = nodes.makeChild(confignode,'Key');
        valueNode   = nodes.makeChild(configNode,'Value');
        KeyNode.parmValue(flows.TFMMenu + 'Header');
        valueNode.setCDataXml(this.makeconfHeader(flows.TFMMenu));
        firstTime = false;
    }

    return firstTime ? null : nodes;
}

private XML makeconfHeader(TFMMenu _menu)
{
    TFMCustomFunctionFlowParmLines  lines;
    TFMCustomFunctionFlowParmLines  tempLines;
    XmlElement                      linesHeader = TFMGetReferenceData::createHeaderAndLine();
    Set                             recSet;
    Map                             dictFields;
    MapEnumerator                   mEnum;
    DictField                       df;
    SetEnumerator                   sEnum;                
    str                             label = 'field';
    int i   = 0;
    while select lines where lines.isFilter && lines.TFMMenu == _menu
    {
        recSet = new Set(Types::Record);

        if (lines.baseType == Types::Record)
        {
            dictFields = lines.getFields();
            if (!dictFields.elements())
            {
                dictFields = TFMHelper::getPrimaryKeysFromTableName(lines.EDTName);
            }
            mEnum = dictFields.getEnumerator();

            while (mEnum.moveNext())
            {
                df = mEnum.currentValue();
                tempLines.baseType = df.baseType();
                if (df.baseType() == Types::Enum)
                {
                    tempLines.EDTName = enumId2Name(df.enumId());
                }
                else 
                {
                    tempLines.EDTName = extendedTypeId2name(df.typeId());
                }
                tempLines.ParmName = mEnum.currentKey();
                recSet.add(tempLines);
            }
        }
        else
        {
            recSet.add(Lines);
        }

        sEnum = recSet.getEnumerator();
        while (sEnum.moveNext())
        {
            tempLines = sEnum.current();
            Label = this.getLabel(tempLines);
            //TODO: reinstate in data collection process 
            /*TFMGetReferenceData::createHeaderConfigurationElement(linesHeader, i*10, tempLines.ParmName,Label, 100, TFMHelper::baseType2InputType(tempLines.baseType), '', '', '',
                                           true, true, 0, intMax(), dateTimeUtil::minValue(),dateTimeUtil::maxValue(), 100, false,
                                           '','','','02,01',false);*/
            i++;
        }
    }
    return linesHeader.parentNode().xml();
}

private str getLabel(TFMCustomFunctionFlowParmLines  _tempLines)
{
    DictType dt;
    DictEnum de;
    str label = '';
    if (_tempLines.EDTName && extendedTypeName2Id(_tempLines.EDTName))
    {
        dt = new DictType(extendedTypeName2Id(_tempLines.EDTName));
        label = dt.label();
    }
    else if (_tempLines.EDTName && enumName2Id(_tempLines.EDTName))
    {
        de = new DictEnum(enumName2Id(_tempLines.EDTName));
        Label = de.label();
    }
    Label = Label ? label : str2Capital(strReplace(_tempLines.ParmName, '_', ''));

    return Label;
}
